import Foundation
import UIKit

/// Shared illustration loader.
///
/// `CachedRemoteImage` and the TextKit reader surface both need the same
/// decoded bitmap for one URL, and illustrations often require the source's
/// own `Referer` / `User-Agent` before the CDN answers. Keeping one loader
/// avoids downloading the same illustration twice and makes the fetch
/// parameters explicit instead of hidden inside a SwiftUI view.
actor RemoteImageLoader {
    static let shared = RemoteImageLoader()

    private let cache = NSCache<NSURL, UIImage>()
    private var inFlight: [NSURL: Task<UIImage?, Never>] = [:]

    private init() {
        cache.countLimit = 160
        cache.totalCostLimit = 64 * 1024 * 1024
    }

    /// Synchronous lookup for layout code that cannot await: a hit renders the
    /// real illustration immediately, a miss renders the placeholder and the
    /// async load fills it in afterwards.
    nonisolated func cachedImage(for url: URL) -> UIImage? {
        cache.object(forKey: url as NSURL)
    }
    ...
}
```

Hmm — `nonisolated` accessing actor state (`cache`) is not allowed in Swift 5.9 unless cache is a Sendable-safe type. NSCache is thread-safe and Sendable-ish but Swift 5.9 with strict concurrency off (SWIFT_VERSION 5.9, no strict concurrency flag) — accessing actor-isolated property from nonisolated method is a compile error regardless ("actor-isolated property 'cache' can not be referenced from a non-isolated context"). To be safe, make the cache a `nonisolated let cache` — NSCache is a class; `nonisolated let` for a let of non-Sendable type in an actor... In Swift 5.9, `nonisolated let` of non-Sendable type is allowed (warning maybe in Swift 6 mode). Safer approach: don't use actor at all. Use a `final class` with a lock, mirroring the existing `ImageMemoryCache` pattern:

```swift
final class RemoteImageLoader: @unchecked Sendable {
    static let shared = RemoteImageLoader()
    private let cache = NSCache<NSURL, UIImage>()
    private let lock = NSLock()
    private var inFlight: [String: Task<UIImage?, Never>] = [:]
    ...
    func cachedImage(for url: URL) -> UIImage? { cache.object(forKey: url as NSURL) }
    func image(for url: URL, headers: [String: String]) async -> UIImage? { ... }
}
```
`@unchecked Sendable` avoids concurrency complaints. NSCache access is thread-safe.

