Downloading: use URLSession.shared.data(for:) with a URLRequest with headers and cachePolicy .returnCacheDataElseLoad. Decode off main thread using DispatchQueue.global like existing code.

```swift
private func download(_ url: URL, headers: [String: String]) async -> UIImage? {
    var request = URLRequest(url: url)
    request.cachePolicy = .returnCacheDataElseLoad
    for (key, value) in headers where !key.isEmpty {
        request.setValue(value, forHTTPHeaderField: key)
    }
    do {
        let (data, response) = try await URLSession.shared.data(for: request)
        guard let http = response as? HTTPURLResponse, (200..<300).contains(http.statusCode) else { return nil }
        guard let decoded = await Self.decode(data) else { return nil }
        cache.setObject(decoded, forKey: url as NSURL, cost: Self.cost(of: decoded))
        return decoded
    } catch { return nil }
}
```
