struct CachedRemoteImage<Placeholder: View>: View {
    let url: URL?
    let contentMode: ContentMode
    let headers: [String: String]
    let placeholder: () -> Placeholder

    @State private var image: UIImage?

    init(url: URL?, contentMode: ContentMode = .fill, headers: [String: String] = [:], @ViewBuilder placeholder: @escaping () -> Placeholder) { ... }

    var body: some View {
        Group {
            if let image { Image(uiImage: image).resizable().aspectRatio(contentMode: contentMode) }
            else { placeholder() }
        }
        .task(id: taskID) { await load() }
    }

    private var taskID: String {
        guard let url else { return "" }
        return url.absoluteString + "|" + headers.keys.sorted().joined(separator: ",")
    }

    private func load() async {
        guard let url else { await MainActor.run { image = nil }; return }
        if let cached = RemoteImageLoader.shared.cachedImage(for: url) { await MainActor.run { image = cached }; return }
        let loaded = await RemoteImageLoader.shared.image(for: url, headers: headers)
        guard let loaded, !Task.isCancelled else { return }
        await MainActor.run { image = loaded }
    }
}
```
