    let missing = urls.filter { RemoteImageLoader.shared.cachedImage(for: $0) == nil }
    guard !missing.isEmpty else { return }
    let key = missing.map(\.absoluteString).joined(separator: "|")
    guard imageLoadTaskKey != key else { return }
    imageLoadTaskKey = key
