        guard let url = ReaderImageSizingPolicy.imageURL(in: paragraphs[idx]) else { continue }
        imageURLs.append(url)
        guard ranges.indices.contains(idx) else { continue }
        let range = ranges[idx]
        let attachment = makeAttachment(for: url, configuration: configuration)
        let attachmentString = NSMutableAttributedString(attachment: attachment)
        // alignment + spacing paragraph style for the illustration line
        let style = NSMutableParagraphStyle()
        style.alignment = .center
        style.paragraphSpacingBefore = CGFloat(configuration.paragraphSpacing + 8)
        style.paragraphSpacing = CGFloat(configuration.paragraphSpacing + 8)
        attachmentString.addAttribute(.paragraphStyle, value: style, range: NSRange(location: 0, length: attachmentString.length))
        let delta = attachmentString.length - range.length
        output.replaceCharacters(in: range, with: attachmentString)
        ranges[idx] = NSRange(location: range.location, length: attachmentString.length)
        if delta != 0 {
            for j in (idx + 1)..<ranges.count {
                ranges[j].location += delta
            }
        }
    }
    imageURLs.reverse()
}
